 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # Color short background gaps between marker cells on shared rows/columns.
    # Demo establishes gaps of up to two cells; further fixtures needed to
    # establish whether more distant gaps are bridged.
    max_gap = 2
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            if 0 < b - a - 1 <= max_gap:
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(ys, ys[1:]):
            if 0 < b - a - 1 <= max_gap:
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

